<script setup lang="ts">
import { computed, ref } from "vue";
import { http } from "@/utils/http";
type Task = Record<string, any>; const rows = ref<Task[]>([]); const loading = ref(false); const error = ref(""); const status = ref(""); const type = ref(""); const detail = ref<Task | null>(null); const counts = computed(() => ({ running: rows.value.filter(row => ['RUNNING','IN_PROGRESS'].includes(String(row.status).toUpperCase())).length, queued: rows.value.filter(row => String(row.status).toUpperCase() === 'QUEUED').length, failed: rows.value.filter(row => String(row.status).toUpperCase() === 'FAILED').length }));
async function load() { loading.value = true; try { const result: any = await http.get("/background-tasks"); const values = Array.isArray(result) ? result : (result?.content || result?.items || []); rows.value = values.filter((row: Task) => (!status.value || String(row.status).toUpperCase() === status.value) && (!type.value || String(row.type || '').toLowerCase().includes(type.value.toLowerCase()))); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "后台任务加载失败"; } finally { loading.value = false; } }
load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">后台任务</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">统一查看导入、备份、恢复、迁移和其他异步任务。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><div class="grid grid-cols-1 md:grid-cols-5 gap-4 mb-5"><el-card shadow="never"><div class="text-sm">运行中</div><div class="text-2xl font-semibold mt-2">{{ counts.running }}</div></el-card><el-card shadow="never"><div class="text-sm">排队中</div><div class="text-2xl font-semibold mt-2">{{ counts.queued }}</div></el-card><el-card shadow="never"><div class="text-sm">24h 失败</div><div class="text-2xl font-semibold mt-2">{{ counts.failed }}</div></el-card><el-card shadow="never"><div class="text-sm">24h 完成</div><div class="text-2xl font-semibold mt-2">{{ rows.length - counts.running - counts.queued - counts.failed }}</div></el-card><el-card shadow="never"><div class="text-sm">长时间运行</div><div class="text-2xl font-semibold mt-2">—</div></el-card></div><div class="flex gap-3 mb-4"><el-select v-model="status" clearable placeholder="状态" @change="load"><el-option label="排队中" value="QUEUED"/><el-option label="运行中" value="RUNNING"/><el-option label="成功" value="COMPLETED"/><el-option label="失败" value="FAILED"/></el-select><el-input v-model="type" clearable placeholder="任务类型" class="max-w-xs" @keyup.enter="load"/></div><el-skeleton v-if="loading" :rows="9" animated/><el-card v-else shadow="never"><el-empty v-if="!rows.length" description="暂无后台任务"/><el-table v-else :data="rows" stripe><el-table-column prop="id" label="Task ID" min-width="240"/><el-table-column prop="type" label="任务类型" width="160"/><el-table-column prop="subsystem" label="子系统" width="150"/><el-table-column prop="status" label="状态" width="120"/><el-table-column prop="progress" label="进度" width="150"/><el-table-column prop="stage" label="当前阶段" min-width="160"/><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link @click="detail = row">详情</el-button></template></el-table-column></el-table></el-card><el-drawer v-model="detail" title="任务检查器" size="480px"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="Task ID">{{ detail.id }}</el-descriptions-item><el-descriptions-item label="所属子系统">{{ detail.subsystem || '—' }}</el-descriptions-item><el-descriptions-item label="状态">{{ detail.status || '—' }}</el-descriptions-item><el-descriptions-item label="当前阶段">{{ detail.stage || '—' }}</el-descriptions-item><el-descriptions-item label="进度">{{ detail.progress || '—' }}</el-descriptions-item><el-descriptions-item label="关联实体">{{ detail.relatedEntityLabel || '安全标签未提供' }}</el-descriptions-item></el-descriptions><el-steps direction="vertical" class="mt-5"><el-step title="排队"/><el-step title="执行"/><el-step title="后处理"/><el-step title="完成 / 失败"/></el-steps></el-drawer></main></template>
